/**
 * Official transparent logo for the family group-wedding committee.
 * Embedded as a base64 PNG data URI so it can be safely inlined in printed
 * PDFs (browser print iframes) and export files without external requests.
 */
export const BRAND_LOGO_DATA_URI = "data:image/png;base64,";
export const BRAND_LOGO_SVG = `<img src="${BRAND_LOGO_DATA_URI}" alt="شعار لجنة الزواج الجماعي" style="width:100%;height:100%;object-fit:contain;display:block;background:transparent;border:0;"/>`;
